functions.determinant:
double determinant(matrix *m)
{
    assert(isSquareMatrix(m));
    switch (m->rows)
    {
    case 1:
        return m->data[0];
    case 2:
        return (m->data[0] * m->data[3]) - (m->data[1] * m->data[2]);
    case 3:
        return (m->data[0] * ((m->data[4] * m->data[8]) - (m->data[5] * m->data[7]))) -
               (m->data[1] * ((m->data[3] * m->data[8]) - (m->data[5] * m->data[6]))) +
               (m->data[2] * ((m->data[3] * m->data[7]) - (m->data[4] * m->data[6])));
    }
    if (isTriangularMatrix(m))
    {
        return diagonalProduct(m);
    }
    matrix *l = ((void *)0);
    matrix *u = ((void *)0);
    matrix *p = ((void *)0);
    double det = pow(-1, luDecomposition(m, &l, &u, &p) - 1) * determinant(l) * determinant(u);
    deleteMatrix(p);
    deleteMatrix(u);
    deleteMatrix(l);
    return det;
}

