matrix *scaleNSpace(matrix *m, double k)
{
    assert(isSquareMatrix(m));
    matrix *n = zeroMatrix(m->cols, m->cols);
    vector *v = zeroVector(m->cols);
    fillVector(&v, k);
    setMainDiagonal(n, v);
    matrix *ref = multiplyMatrices(m, n);
    deleteVector(v);
    deleteMatrix(n);
    return ref;
}

